import { useEffect } from 'react';
import { useSelector } from 'react-redux';

import { hasErrorType } from '../helpers/errors';
import { conversationByID } from '../logic/conversations/conversationsSelectors';
import { ConversationState } from '../logic/conversations/conversationsTypes';
import { messageByID } from '../logic/messages/messagesSelectors';
import { MessageState } from '../logic/messages/messagesTypes';
import { RootState } from '../logic/store';

const cacheEntryIsFailedLoading = (
    conversationMode: boolean,
    cacheEntry: MessageState | ConversationState | undefined
) => {
    if (conversationMode) {
        return hasErrorType(cacheEntry?.errors, 'notExist');
    }
    const messageExtended = cacheEntry as MessageState;
    return messageExtended?.data?.ID && !messageExtended?.data?.Subject;
};

interface Props {
    conversationMode: boolean;
    elementID?: string;
    onBack: () => void;
    loading: boolean;
    labelID: string;
}

export const useShouldMoveOut = ({ conversationMode, elementID = '', labelID, loading, onBack }: Props) => {
    const message = useSelector((state: RootState) => messageByID(state, { ID: elementID }));
    const conversation = useSelector((state: RootState) => conversationByID(state, { ID: elementID }));
    const cacheEntry = conversationMode ? conversation : message;

    const onChange = (labelIds: string[] | undefined) => {
        // Move out if the element is not present in the cache anymore
        if (!labelIds) {
            onBack();
            return;
        }

        // Move out if the element doesn't contain the current label
        if (!labelIds.includes(labelID)) {
            onBack();
            return;
        }
    };

    useEffect(() => {
        if (!loading && !conversationMode && message?.data?.LabelIDs) {
            // Not sure why, but message from the selector can be a render late here
            onChange(message?.data?.LabelIDs);
        }
    }, [message?.data?.LabelIDs, loading]);

    useEffect(() => {
        if (!loading && conversationMode && conversation?.Conversation.Labels) {
            // Not sure why, but message from the selector can be a render late here
            onChange(conversation?.Conversation.Labels.map((label) => label.ID));
        }
    }, [conversation?.Conversation.Labels, loading]);

    useEffect(() => {
        if (!elementID || !cacheEntry) {
            return;
        }

        // Move out of a non existing element
        if (!loading && (!cacheEntry || cacheEntryIsFailedLoading(conversationMode, cacheEntry))) {
            onBack();
            return;
        }
    }, [elementID, loading, conversationMode, cacheEntry]);
};

import { memo, useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useHistory, useLocation } from 'react-router-dom';

import {
    ErrorBoundary,
    PrivateMainArea,
    classnames,
    useCalendarUserSettings,
    useCalendars,
    useFolders,
    useItemsSelection,
    useLabels,
} from '@proton/components';
import { useCalendarsInfoCoreListener } from '@proton/components/containers/eventManager/calendar/useCalendarsInfoListener';
import { VIEW_MODE } from '@proton/shared/lib/constants';
import { getSearchParams } from '@proton/shared/lib/helpers/url';
import { MailSettings, UserSettings } from '@proton/shared/lib/interfaces';
import { Message } from '@proton/shared/lib/interfaces/mail/Message';
import { isDraft } from '@proton/shared/lib/mail/messages';

import ConversationView from '../../components/conversation/ConversationView';
import List from '../../components/list/List';
import MessageOnlyView from '../../components/message/MessageOnlyView';
import Toolbar from '../../components/toolbar/Toolbar';
import PlaceholderView from '../../components/view/PlaceholderView';
import { MAILTO_PROTOCOL_HANDLER_SEARCH_PARAM } from '../../constants';
import { isMessage, isSearch as testIsSearch } from '../../helpers/elements';
import { getFolderName } from '../../helpers/labels';
import { isColumnMode, isConversationMode } from '../../helpers/mailSettings';
import {
    extractSearchParameters,
    filterFromUrl,
    pageFromUrl,
    setFilterInUrl,
    setPageInUrl,
    setParamsInLocation,
    setSortInUrl,
    sortFromUrl,
} from '../../helpers/mailboxUrl';
import { MARK_AS_STATUS, useMarkAs } from '../../hooks/actions/useMarkAs';
import { usePermanentDelete } from '../../hooks/actions/usePermanentDelete';
import { ComposeTypes } from '../../hooks/composer/useCompose';
import { useApplyEncryptedSearch } from '../../hooks/mailbox/useApplyEncryptedSearch';
import { useElements, useGetElementsFromIDs } from '../../hooks/mailbox/useElements';
import { useMailboxFocus } from '../../hooks/mailbox/useMailboxFocus';
import { useMailboxHotkeys } from '../../hooks/mailbox/useMailboxHotkeys';
import { useMailboxPageTitle } from '../../hooks/mailbox/useMailboxPageTitle';
import useNewEmailNotification from '../../hooks/mailbox/useNewEmailNotification';
import usePreLoadElements from '../../hooks/mailbox/usePreLoadElements';
import { useWelcomeFlag } from '../../hooks/mailbox/useWelcomeFlag';
import { useDeepMemo } from '../../hooks/useDeepMemo';
import { useResizeMessageView } from '../../hooks/useResizeMessageView';
import { Filter, SearchParameters, Sort } from '../../models/tools';
import { Breakpoints } from '../../models/utils';
import { useOnCompose, useOnMailTo } from '../ComposeProvider';
import { MailboxContainerContextProvider } from './MailboxContainerProvider';

interface Props {
    labelID: string;
    mailSettings: MailSettings;
    userSettings: UserSettings;
    breakpoints: Breakpoints;
    elementID?: string;
    messageID?: string;
    isComposerOpened: boolean;
    toolbarBordered?: boolean;
}

const MailboxContainer = ({
    labelID: inputLabelID,
    mailSettings,
    userSettings,
    breakpoints,
    elementID,
    messageID,
    isComposerOpened,
    toolbarBordered,
}: Props) => {
    const location = useLocation();
    const history = useHistory();
    const [labels] = useLabels();
    const [folders] = useFolders();
    const getElementsFromIDs = useGetElementsFromIDs();
    const markAs = useMarkAs();
    const listRef = useRef<HTMLDivElement>(null);
    const forceRowMode = breakpoints.isNarrow || breakpoints.isTablet;
    const columnModeSetting = isColumnMode(mailSettings);
    const columnMode = columnModeSetting && !forceRowMode;
    const columnLayout = columnModeSetting || forceRowMode;
    const labelIDs = (labels || []).map(({ ID }) => ID);
    const messageContainerRef = useRef<HTMLElement>(null);
    const mainAreaRef = useRef<HTMLDivElement>(null);
    const resizeAreaRef = useRef<HTMLButtonElement>(null);

    const onMailTo = useOnMailTo();

    const { enableResize, resetWidth, scrollBarWidth, isResizing } = useResizeMessageView(
        mainAreaRef,
        resizeAreaRef,
        listRef
    );

    const page = pageFromUrl(location);
    const searchParams = getSearchParams(location.hash);
    const isConversationContentView = mailSettings.ViewMode === VIEW_MODE.GROUP;
    const searchParameters = useDeepMemo<SearchParameters>(() => extractSearchParameters(location), [location]);
    const isSearch = testIsSearch(searchParameters);
    const sort = useMemo<Sort>(() => sortFromUrl(location, inputLabelID), [searchParams.sort, inputLabelID]);
    const filter = useMemo<Filter>(() => filterFromUrl(location), [searchParams.filter]);

    // Open a composer when the url contains a mailto query
    useEffect(() => {
        if (!isSearch && location.hash) {
            const searchParams = location.hash.substring(1).split('&');
            searchParams.forEach((param) => {
                const pair = param.split('=');
                if (pair[0] === MAILTO_PROTOCOL_HANDLER_SEARCH_PARAM) {
                    try {
                        onMailTo(decodeURIComponent(pair[1]));
                    } catch (e: any) {
                        console.error(e);
                    }
                }
            });
        }
    }, [location.hash, isSearch]);

    const handlePage = useCallback((pageNumber: number) => {
        history.push(setPageInUrl(history.location, pageNumber));
    }, []);
    const handleSort = useCallback((sort: Sort) => history.push(setSortInUrl(history.location, sort)), []);
    const handleFilter = useCallback((filter: Filter) => history.push(setFilterInUrl(history.location, filter)), []);

    const [isMessageOpening, setIsMessageOpening] = useState(false);

    const onMessageLoad = () => setIsMessageOpening(true);
    const onMessageReady = useCallback(() => setIsMessageOpening(false), [setIsMessageOpening]);

    const elementsParams = {
        conversationMode: isConversationMode(inputLabelID, mailSettings, location),
        labelID: inputLabelID,
        page: pageFromUrl(location),
        sort,
        filter,
        search: searchParameters,
        onPage: handlePage,
    };

    const { labelID, elements, elementIDs, loading, placeholderCount, total } = useElements(elementsParams);
    const { handleDelete: permanentDelete, modal: deleteModal } = usePermanentDelete(labelID);
    useApplyEncryptedSearch(elementsParams);

    const handleBack = useCallback(() => history.push(setParamsInLocation(history.location, { labelID })), [labelID]);

    const onCompose = useOnCompose();

    useMailboxPageTitle(labelID, location);

    const {
        checkedIDs,
        selectedIDs,
        handleCheck,
        handleCheckAll,
        handleCheckOne,
        handleCheckOnlyOne,
        handleCheckRange,
    } = useItemsSelection(elementID, elementIDs, [elementID, labelID]);

    useNewEmailNotification(() => handleCheckAll(false));

    // Launch two calendar-specific API calls here to boost calendar widget performance
    useCalendars();
    useCalendarUserSettings();
    // listen to calendar "core" updates
    useCalendarsInfoCoreListener();

    const elementsLength = loading ? placeholderCount : elements.length;
    const showToolbar = !breakpoints.isNarrow || !elementID;
    const showList = columnMode || !elementID;
    const showContentPanel = (columnMode && !!elementsLength) || !!elementID;
    const showPlaceholder = !breakpoints.isNarrow && (!elementID || !!checkedIDs.length);
    const showContentView = showContentPanel && !!elementID;
    const elementIDForList = checkedIDs.length ? undefined : elementID;

    const { focusIndex, getFocusedId, setFocusIndex, handleFocus, focusOnLastMessage } = useMailboxFocus({
        elementIDs,
        page,
        showList,
        listRef,
        labelID,
        isComposerOpened,
    });

    const welcomeFlag = useWelcomeFlag([labelID, selectedIDs.length]);

    const handleElement = useCallback(
        (elementID: string | undefined, preventComposer = false) => {
            // Using the getter to prevent having elements in dependency of the callback
            const [element] = getElementsFromIDs([elementID || '']);

            if (isMessage(element) && isDraft(element) && !preventComposer) {
                onCompose({
                    type: ComposeTypes.existingDraft,
                    existingDraft: { localID: element.ID as string, data: element as Message },
                    fromUndo: false,
                });
            }
            if (isConversationContentView && isMessage(element)) {
                onMessageLoad();
                history.push(
                    setParamsInLocation(history.location, {
                        labelID,
                        elementID: (element as Message).ConversationID,
                        messageID: element.ID,
                    })
                );
            } else {
                onMessageLoad();
                history.push(setParamsInLocation(history.location, { labelID, elementID: element.ID }));
            }
            handleCheckAll(false);
        },
        [onCompose, isConversationContentView, labelID]
    );

    const handleMarkAs = useCallback(
        async (status: MARK_AS_STATUS) => {
            const isUnread = status === MARK_AS_STATUS.UNREAD;
            const elements = getElementsFromIDs(selectedIDs);
            if (isUnread) {
                handleBack();
            }
            await markAs(elements, labelID, status);
        },
        [selectedIDs, labelID, handleBack]
    );

    const handleDelete = useCallback(async () => {
        await permanentDelete(selectedIDs);
    }, [selectedIDs, permanentDelete]);

    const conversationMode = isConversationMode(labelID, mailSettings, location);

    usePreLoadElements(elementIDs, conversationMode, labelID);

    const {
        elementRef,
        labelDropdownToggleRef,
        moveDropdownToggleRef,
        moveScheduledModal,
        moveAllModal,
        moveToSpamModal,
        permanentDeleteModal,
        moveToFolder,
    } = useMailboxHotkeys(
        {
            labelID,
            elementID,
            messageID,
            elementIDs,
            checkedIDs,
            selectedIDs,
            focusIndex,
            columnLayout,
            isMessageOpening,
            location,
        },
        {
            focusOnLastMessage,
            getFocusedId,
            handleBack,
            handleCheck,
            handleCheckOnlyOne,
            handleCheckRange,
            handleElement,
            handleFilter,
            handleCheckAll,
            setFocusIndex,
        }
    );

    const handleMove = useCallback(
        async (LabelID: string) => {
            const folderName = getFolderName(LabelID, folders);
            const elements = getElementsFromIDs(selectedIDs);
            await moveToFolder(elements, LabelID, folderName, labelID, false);
            if (selectedIDs.includes(elementID || '')) {
                handleBack();
            }
        },
        [selectedIDs, elementID, labelID, labelIDs, folders, handleBack]
    );

    return (
        <MailboxContainerContextProvider
            isResizing={isResizing}
            containerRef={messageContainerRef}
            elementID={elementID}
        >
            <div
                ref={elementRef}
                tabIndex={-1}
                className="flex-item-fluid flex flex-column flex-nowrap outline-none"
                data-testid="mailbox"
            >
                {showToolbar && (
                    <ErrorBoundary small>
                        <Toolbar
                            labelID={labelID}
                            elementID={elementID}
                            messageID={messageID}
                            selectedIDs={selectedIDs}
                            checkedIDs={checkedIDs}
                            elementIDs={elementIDs}
                            columnMode={columnMode}
                            conversationMode={conversationMode}
                            breakpoints={breakpoints}
                            onCheck={handleCheck}
                            page={page}
                            total={total}
                            isSearch={isSearch}
                            onPage={handlePage}
                            onBack={handleBack}
                            onElement={handleElement}
                            onMarkAs={handleMarkAs}
                            onMove={handleMove}
                            onDelete={handleDelete}
                            labelDropdownToggleRef={labelDropdownToggleRef}
                            moveDropdownToggleRef={moveDropdownToggleRef}
                            bordered={toolbarBordered}
                        />
                    </ErrorBoundary>
                )}
                <PrivateMainArea
                    className="flex"
                    hasToolbar={showToolbar}
                    hasRowMode={!showContentPanel}
                    ref={mainAreaRef}
                >
                    <ErrorBoundary>
                        <List
                            ref={listRef}
                            show={showList}
                            conversationMode={conversationMode}
                            labelID={labelID}
                            loading={loading}
                            placeholderCount={placeholderCount}
                            columnLayout={columnLayout}
                            elementID={elementIDForList}
                            elements={elements}
                            checkedIDs={checkedIDs}
                            onCheck={handleCheck}
                            onClick={handleElement}
                            isSearch={isSearch}
                            breakpoints={breakpoints}
                            page={page}
                            total={total}
                            onPage={handlePage}
                            onFocus={handleFocus}
                            onCheckOne={handleCheckOne}
                            filter={filter}
                            resizeAreaRef={resizeAreaRef}
                            enableResize={enableResize}
                            resetWidth={resetWidth}
                            showContentPanel={showContentPanel}
                            scrollBarWidth={scrollBarWidth}
                            onMarkAs={handleMarkAs}
                            onDelete={handleDelete}
                            onMove={handleMove}
                            onBack={handleBack}
                            mailSettings={mailSettings}
                            userSettings={userSettings}
                            sort={sort}
                            onSort={handleSort}
                            onFilter={handleFilter}
                        />
                    </ErrorBoundary>
                    <ErrorBoundary>
                        <section
                            className={classnames([
                                'view-column-detail flex flex-column flex-item-fluid flex-nowrap relative',
                                !showContentPanel && 'hidden',
                                showContentView ? 'no-scroll' : 'scroll-if-needed',
                            ])}
                        >
                            {showPlaceholder && (
                                <PlaceholderView
                                    welcomeFlag={welcomeFlag}
                                    labelID={labelID}
                                    checkedIDs={checkedIDs}
                                    onCheckAll={handleCheckAll}
                                />
                            )}
                            {showContentView &&
                                (isConversationContentView ? (
                                    <ConversationView
                                        hidden={showPlaceholder}
                                        labelID={labelID}
                                        messageID={messageID}
                                        mailSettings={mailSettings}
                                        conversationID={elementID as string}
                                        onBack={handleBack}
                                        breakpoints={breakpoints}
                                        onMessageReady={onMessageReady}
                                        columnLayout={columnLayout}
                                        isComposerOpened={isComposerOpened}
                                        containerRef={messageContainerRef}
                                    />
                                ) : (
                                    <MessageOnlyView
                                        hidden={showPlaceholder}
                                        labelID={labelID}
                                        mailSettings={mailSettings}
                                        messageID={elementID as string}
                                        onBack={handleBack}
                                        breakpoints={breakpoints}
                                        onMessageReady={onMessageReady}
                                        columnLayout={columnLayout}
                                        isComposerOpened={isComposerOpened}
                                    />
                                ))}
                        </section>
                    </ErrorBoundary>
                </PrivateMainArea>
            </div>
            {permanentDeleteModal}
            {moveScheduledModal}
            {moveAllModal}
            {moveToSpamModal}
            {deleteModal}
        </MailboxContainerContextProvider>
    );
};

export default memo(MailboxContainer);

import { RefObject, memo, useEffect, useRef } from 'react';
import { useDispatch } from 'react-redux';

import { Scroll } from '@proton/atoms';
import { classnames, useLabels, useToggle } from '@proton/components';
import { isEditing } from '@proton/shared/lib/busy';
import { MAILBOX_LABEL_IDS } from '@proton/shared/lib/constants';
import { MailSettings } from '@proton/shared/lib/interfaces';
import { Message } from '@proton/shared/lib/interfaces/mail/Message';
import { isDraft } from '@proton/shared/lib/mail/messages';

import { useEncryptedSearchContext } from '../../containers/EncryptedSearchProvider';
import { hasLabel } from '../../helpers/elements';
import { findMessageToExpand } from '../../helpers/message/messageExpandable';
import { useConversation } from '../../hooks/conversation/useConversation';
import { useConversationFocus } from '../../hooks/conversation/useConversationFocus';
import { useConversationHotkeys } from '../../hooks/conversation/useConversationHotkeys';
import { useGetMessage } from '../../hooks/message/useMessage';
import { usePlaceholders } from '../../hooks/usePlaceholders';
import { useShouldMoveOut } from '../../hooks/useShouldMoveOut';
import { removeAllQuickReplyFlags } from '../../logic/messages/draft/messagesDraftActions';
import { Breakpoints } from '../../models/utils';
import MessageView, { MessageViewRef } from '../message/MessageView';
import ConversationErrorBanner from './ConversationErrorBanner';
import ConversationHeader from './ConversationHeader';
import TrashWarning from './TrashWarning';
import UnreadMessages from './UnreadMessages';

const { TRASH, ALL_MAIL } = MAILBOX_LABEL_IDS;

interface Props {
    hidden: boolean;
    labelID: string;
    conversationID: string;
    messageID?: string;
    mailSettings: MailSettings;
    onBack: () => void;
    breakpoints: Breakpoints;
    onMessageReady: () => void;
    columnLayout: boolean;
    isComposerOpened: boolean;
    containerRef: RefObject<HTMLElement>;
}

const DEFAULT_FILTER_VALUE = true;

const ConversationView = ({
    hidden,
    labelID,
    conversationID: inputConversationID,
    messageID,
    mailSettings,
    onBack,
    breakpoints,
    onMessageReady,
    columnLayout,
    isComposerOpened,
    containerRef,
}: Props) => {
    const dispatch = useDispatch();
    const getMessage = useGetMessage();
    const { isSearchResult } = useEncryptedSearchContext();
    const [labels = []] = useLabels();
    const {
        conversationID,
        conversation: conversationState,
        pendingRequest,
        loadingConversation,
        loadingMessages,
        handleRetry,
    } = useConversation(inputConversationID, messageID);
    const { state: filter, toggle: toggleFilter, set: setFilter } = useToggle(DEFAULT_FILTER_VALUE);
    useShouldMoveOut({
        conversationMode: true,
        elementID: conversationID,
        loading: pendingRequest || loadingConversation || loadingMessages,
        onBack,
        labelID,
    });
    const messageViewsRefs = useRef({} as { [messageID: string]: MessageViewRef | undefined });

    const wrapperRef = useRef<HTMLDivElement>(null);

    const { Conversation: conversation, Messages: inputMessages = [] } = conversationState || {};
    const messages = usePlaceholders(inputMessages, loadingMessages, conversation?.NumMessages || 1) as Message[];

    const inTrash = labelID === TRASH;
    const inAllMail = labelID === ALL_MAIL;
    const filteredMessages = messages.filter(
        (message) => inAllMail || inTrash === hasLabel(message, TRASH) || isSearchResult(message.ID)
    );

    const messagesToShow = !loadingMessages && filter ? filteredMessages : messages;

    const messagesWithoutQuickReplies = messagesToShow.filter((message) => {
        const messageFromState = getMessage(message.ID);
        return !messageFromState?.draftFlags?.isQuickReply;
    });

    const showTrashWarning = !loadingMessages && filteredMessages.length !== messages.length;
    const messageInUrl = conversationState?.Messages?.find((message) => message.ID === messageID);
    const loading = loadingConversation || loadingMessages;
    const showConversationError = !loading && conversationState?.Conversation?.Subject === undefined;
    const showMessagesError = !loading && !showConversationError && !conversationState?.Messages;

    const { focusIndex, handleFocus, handleScrollToMessage, handleBlur, getFocusedId } =
        useConversationFocus(messagesWithoutQuickReplies);

    const expandMessage = (messageID: string | undefined, scrollTo = false) => {
        messageViewsRefs.current[messageID || '']?.expand();
        const index = messagesToShow.findIndex((message) => message.ID === messageID);
        // isEditing is used to prevent the focus to be set on the message when the user is editing, otherwise it triggers shortcuts
        if (index !== undefined && !isEditing()) {
            handleFocus(index, {scrollTo});
        }
    };

    const { elementRef } = useConversationHotkeys(
        { messages: messagesWithoutQuickReplies, focusIndex },
        { handleFocus, getFocusedId, expandMessage }
    );

    // Open the first message of a conversation if none selected in URL
    useEffect(() => {
        if (!loadingMessages && !messageID) {
            expandMessage(findMessageToExpand(labelID, messagesWithoutQuickReplies)?.ID);
        }
    }, [conversationID, messageID, loadingMessages]);

    // Open the message in URL
    useEffect(() => {
        if (!loadingMessages && messageID && !isDraft(messageInUrl)) {
            expandMessage(messageID, true);
        }
    }, [conversationID, messageID, loadingMessages, messageInUrl]);

    useEffect(() => {
        setFilter(DEFAULT_FILTER_VALUE);
    }, [inputConversationID]);

    useEffect(() => {
        // When the user is switching conversation we need to remove potential quick replies draft flags
        dispatch(removeAllQuickReplyFlags());
    }, [conversationID]);

    const handleOpenQuickReply = (messageIndex?: number) => {
        handleScrollToMessage(messageIndex, 'end');
    };

    const handleClickUnread = (messageID: string) => {
        expandMessage(messageID);
    };

    const trashWarningRef = useRef<HTMLDivElement>(null);
    const onlyTrashInConversation = !loadingMessages && !filteredMessages.length;

    useEffect(() => {
        if (onlyTrashInConversation) {
            // unblock J/K shortcuts
            setTimeout(onMessageReady);
            if (!columnLayout) {
                trashWarningRef.current?.parentElement?.focus();
            }
        }
    }, [onlyTrashInConversation, conversationID, columnLayout]);

    return showConversationError ? (
        <ConversationErrorBanner errors={conversationState?.errors} onRetry={handleRetry} />
    ) : (
            <Scroll className={classnames([hidden && 'hidden'])} customContainerRef={containerRef}>
                <ConversationHeader
                    className={classnames([hidden && 'hidden'])}
                    loading={loadingConversation}
                    element={conversation}
                />
                <div ref={wrapperRef} className="flex-item-fluid pr1 pl1 w100">
                    <div className="outline-none" ref={elementRef} tabIndex={-1}>
                        {showMessagesError ? (
                            <ConversationErrorBanner errors={conversationState?.errors} onRetry={handleRetry} />
                        ) : null}
                        {showTrashWarning && (
                            <TrashWarning
                                ref={trashWarningRef}
                                inTrash={inTrash}
                                filter={filter}
                                onToggle={toggleFilter}
                            />
                        )}
                        {messagesWithoutQuickReplies.map((message, index) => (
                            <MessageView
                                key={message.ID}
                                ref={(ref) => {
                                    messageViewsRefs.current[message.ID] = ref || undefined;
                                }}
                                labelID={labelID}
                                conversationMode
                                loading={loadingMessages}
                                message={message}
                                labels={labels}
                                mailSettings={mailSettings}
                                conversationIndex={index}
                                conversationID={conversationID}
                                onBack={onBack}
                                breakpoints={breakpoints}
                                onFocus={handleFocus}
                                onBlur={handleBlur}
                                hasFocus={index === focusIndex}
                                onMessageReady={onMessageReady}
                                columnLayout={columnLayout}
                                isComposerOpened={isComposerOpened}
                                containerRef={containerRef}
                                wrapperRef={wrapperRef}
                                onOpenQuickReply={handleOpenQuickReply}
                            />
                        ))}
                    </div>
                </div>
                <UnreadMessages
                    conversationID={conversationID}
                    messages={conversationState?.Messages}
                    onClick={handleClickUnread}
                />
            </Scroll>
    );
};

export default memo(ConversationView);

import { useEffect, useRef, useState } from 'react';
import { useDispatch } from 'react-redux';

import { Scroll } from '@proton/atoms';
import { classnames, useHotkeys, useLabels } from '@proton/components';
import { MailSettings } from '@proton/shared/lib/interfaces';
import { Message } from '@proton/shared/lib/interfaces/mail/Message';
import { isDraft } from '@proton/shared/lib/mail/messages';

import useClickOutsideFocusedMessage from '../../hooks/conversation/useClickOutsideFocusedMessage';
import { useLoadMessage } from '../../hooks/message/useLoadMessage';
import { useMessage } from '../../hooks/message/useMessage';
import { useShouldMoveOut } from '../../hooks/useShouldMoveOut';
import { MessageWithOptionalBody } from '../../logic/messages/messagesTypes';
import { removeAllQuickReplyFlags } from '../../logic/messages/draft/messagesDraftActions';
import { Breakpoints } from '../../models/utils';
import ConversationHeader from '../conversation/ConversationHeader';
import MessageView, { MessageViewRef } from './MessageView';

interface Props {
    hidden: boolean;
    labelID: string;
    messageID: string;
    mailSettings: MailSettings;
    onBack: () => void;
    breakpoints: Breakpoints;
    onMessageReady: () => void;
    columnLayout: boolean;
    isComposerOpened: boolean;
}

const MessageOnlyView = ({
    hidden,
    labelID,
    messageID,
    mailSettings,
    onBack,
    breakpoints,
    onMessageReady,
    columnLayout,
    isComposerOpened,
}: Props) => {
    const [labels = []] = useLabels();

    const [isMessageFocused, setIsMessageFocused] = useState(false);
    const [isMessageReady, setIsMessageReady] = useState(false);
    const { message, messageLoaded, bodyLoaded } = useMessage(messageID);
    const load = useLoadMessage(message.data || ({ ID: messageID } as MessageWithOptionalBody));

    const dispatch = useDispatch();

    useShouldMoveOut({ conversationMode: false, elementID: messageID, loading: !bodyLoaded, onBack, labelID });

    // Manage loading the message
    useEffect(() => {
        if (!messageLoaded) {
            void load();
        }
    }, [messageLoaded]);

    useEffect(() => {
        // When the user is switching message we need to remove potential quick replies draft flags
        dispatch(removeAllQuickReplyFlags());
    }, [messageID]);

    // Message content could be undefined
    const data = message.data || ({ ID: messageID } as Message);

    const messageContainerRef = useRef(null);

    useHotkeys(messageContainerRef, [
        [
            'ArrowLeft',
            (e) => {
                e.preventDefault();
                e.stopPropagation();

                const element = document.querySelector('[data-shortcut-target="navigation-link inbox"]') as HTMLElement;
                if (element) {
                    element.focus();
                    setIsMessageFocused(false);
                }
            },
        ],
    ]);

    const messageRef = useRef<MessageViewRef>(null);

    useClickOutsideFocusedMessage(messageID, () => {
        setIsMessageFocused(false);
    });
    const handleBlurCallback = () => {
        setIsMessageFocused(false);
    };
    const handleFocusCallback = () => {
        setIsMessageFocused(true);
    };

    const handleMessageReadyCallback = () => {
        setIsMessageReady(true);
        onMessageReady();
    };

    useEffect(() => {
        if (!isDraft(message.data)) {
            messageRef?.current?.expand();
        }

        return () => {
            setIsMessageReady(false);
        };
    }, [messageID]);

    const handleGetMessageElement = () => {
        const selector = `[data-shortcut-target="message-container"][data-message-id="${messageID}"]`;

        return document.querySelector(selector) as HTMLElement;
    };

    const handleOpenQuickReply = () => {
        const element = handleGetMessageElement();

        element?.scrollIntoView({ block: 'end', behavior: 'smooth' });
    };

    useEffect(() => {
        if (messageID && isMessageReady) {
            const element = handleGetMessageElement();
            element?.focus({ preventScroll: true });
            setIsMessageFocused(true);
        }
    }, [messageID, isMessageReady]);

    return (
            <Scroll className={classnames([hidden && 'hidden'])}>
                <ConversationHeader
                    className={classnames([hidden && 'hidden'])}
                    loading={!messageLoaded}
                    element={message.data}
                />
                <div className="flex-item-fluid px1 mt1 max-w100 outline-none" ref={messageContainerRef} tabIndex={-1}>
                    <MessageView
                        // Break the reuse of the MessageView accross multiple message
                        // Solve a lot of reuse issues, reproduce the same as in conversation mode with a map on conversation messages
                        key={message.localID}
                        ref={messageRef}
                        labelID={labelID}
                        conversationMode={false}
                        loading={!messageLoaded}
                        message={data}
                        labels={labels}
                        mailSettings={mailSettings}
                        onBack={onBack}
                        breakpoints={breakpoints}
                        onMessageReady={handleMessageReadyCallback}
                        columnLayout={columnLayout}
                        isComposerOpened={isComposerOpened}
                        onBlur={handleBlurCallback}
                        onFocus={handleFocusCallback}
                        hasFocus={isMessageFocused}
                        onOpenQuickReply={handleOpenQuickReply}
                    />
                </div>
            </Scroll>
    );
};

export default MessageOnlyView;

